(function(){
'use strict';
const data=window.STAGE_DATA,M=window.StageModel,$=id=>document.getElementById(id),week=['日','一','二','三','四','五','六'];
const today=M.taipeiToday(),base=M.parseDate(today>=data.start&&today<=data.end?today:data.start);
const state={year:base.getFullYear(),month:base.getMonth(),selected:M.dateKey(base),region:'all',city:'all',query:''};
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shortDate=s=>{const d=M.parseDate(s);return `${d.getMonth()+1} 月 ${d.getDate()} 日`};
const weekday=s=>'週'+week[M.parseDate(s).getDay()];
function dateSelect(key,scroll=false){state.selected=key;const d=M.parseDate(key);state.year=d.getFullYear();state.month=d.getMonth();render();if(scroll&&window.matchMedia('(max-width:760px)').matches)document.querySelector('.day-panel').scrollIntoView({behavior:'smooth',block:'start'})}
function resetFilters(){state.region='all';state.city='all';state.query='';$('search').value='';render()}
function renderFilters(){const counts=Object.keys(M.regions).reduce((o,r)=>({...o,[r]:M.sessions(data,{region:r}).length}),{});$('regions').innerHTML=[['all','全台'],...Object.entries(M.regions)].map(([key,label])=>`<button class="region-button ${state.region===key?'active':''}" data-region="${key}" aria-pressed="${state.region===key}">${label}<small>${key==='all'?M.sessions(data).length:counts[key]}</small></button>`).join('');$('regions').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{state.region=b.dataset.region;state.city='all';render()}));const cities=[...new Set(data.productions.filter(p=>state.region==='all'||p.region===state.region).map(p=>p.city))].sort((a,b)=>a.localeCompare(b,'zh-Hant'));$('city-filter').innerHTML='<option value="all">所有城市</option>'+cities.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('city-filter').value=state.city;}
function renderCalendar(list){$('month-label').textContent=`${state.year} 年 ${state.month+1} 月`;$('month-en').textContent=new Intl.DateTimeFormat('en',{month:'long'}).format(new Date(state.year,state.month,1)).toUpperCase();const first=`${state.year}-${M.pad(state.month+1)}-01`,last=M.dateKey(new Date(state.year,state.month+1,0));$('month-note').textContent=last<data.start||first>data.end?'此月份不在樣本收錄期間內。可回到 2026 年 10 月至 2027 年 1 月查看。':state.month===9&&state.year===2026?'10 月 22 日起為本次樣本收錄範圍。':state.month===0&&state.year===2027?'本次樣本收錄至 1 月 21 日。':'';$('calendar').innerHTML=M.monthCells(state.year,state.month).map(c=>{const items=list.filter(s=>s.date===c.key),rs=[...new Set(items.map(s=>s.production.region))];return `<button class="day ${c.inMonth?'':'other'} ${c.key===state.selected?'selected':''} ${c.key===today?'today':''} ${c.key<data.start||c.key>data.end?'outside':''}" data-date="${c.key}" aria-label="${c.key}，${items.length?'已收錄 '+items.length+' 場':'尚未收錄場次'}${c.key===today?'，今天':''}" aria-pressed="${c.key===state.selected}"><span class="day-number">${c.day}</span><span class="day-dots" aria-hidden="true">${rs.map(r=>`<i class="dot ${r}"></i>`).join('')}${items.length?`<span class="day-total">${items.length}</span>`:''}</span></button>`}).join('');$('calendar').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>dateSelect(b.dataset.date)));$('jump-date').value=state.selected;}
function eventCard(g){const p=g.production;return `<article class="event-card"><div class="event-category"><span class="event-city"><i class="dot ${p.region}"></i>${esc(p.city)} · ${M.regions[p.region]}</span><span>${esc(p.category||'音樂劇')}</span></div><h4>${esc(p.title)}</h4>${p.subtitle?`<p class="subtitle">${esc(p.subtitle)}</p>`:''}<p class="event-meta">${esc(p.venue)}</p><div class="time-chips" aria-label="演出時間">${g.times.map(t=>`<span class="time-chip">${esc(t)}</span>`).join('')}</div><p class="event-summary">${esc(p.summary)}</p>${p.notes?`<p class="event-notice">${esc(p.notes)}</p>`:''}<a class="official-link" href="${esc(p.ticketUrl||p.sourceUrl)}" target="_blank" rel="noopener noreferrer">官方節目與購票 <span aria-hidden="true">↗</span></a><p class="verified">官方場次核對 ${esc(p.checkedAt||data.checkedAt)} · 台灣時間</p></article>`}
function renderDay(list){const allForDay=M.sessions(data).filter(s=>s.date===state.selected),forDay=list.filter(s=>s.date===state.selected);$('selected-label').textContent=shortDate(state.selected);$('selected-weekday').textContent=weekday(state.selected);$('selected-eyebrow').textContent=state.selected===today?"TODAY'S PROGRAMME":"THE DAY'S PROGRAMME";$('day-count').textContent=forDay.length?`已收錄 ${forDay.length} 場 · ${new Set(forDay.map(s=>s.production.id)).size} 部作品`:'此條件下尚無已收錄場次';if(forDay.length){$('day-events').innerHTML=M.groupSessions(forDay).map(eventCard).join('');return}const outside=state.selected<data.start||state.selected>data.end,filtered=allForDay.length>0;const next=list.find(s=>s.date>=state.selected)||list[0];$('day-events').innerHTML=`<div class="empty-day"><span class="empty-symbol" aria-hidden="true">◌</span><h4>${outside?'這一天，不在樣本期間內':filtered?'換個地方，看看其他舞台':'這一天，還沒有收錄場次'}</h4><p>${outside?'樣本涵蓋 2026/10/22 至 2027/01/21。':filtered?'當天有其他地區或關鍵字條件外的演出，可以清除篩選查看。':'這不是「沒有演出」的意思。先逛逛已確認的日期，找到下一個值得期待的晚上。'}</p>${filtered?'<button id="clear-day">清除篩選</button>':next?`<button id="next-date">看 ${shortDate(next.date)} 的演出 <span aria-hidden="true">↗</span></button>`:''}</div>`;if($('clear-day'))$('clear-day').addEventListener('click',resetFilters);if($('next-date'))$('next-date').addEventListener('click',()=>dateSelect(next.date));}
function renderUpcoming(list){const anchor=state.selected<data.start?data.start:state.selected;const groups=M.groupSessions(list.filter(s=>s.date>=anchor)).slice(0,3);$('upcoming-summary').textContent=`從 ${shortDate(anchor)} 起 · 依目前篩選`;if(!groups.length){$('upcoming-list').innerHTML=`<p class="no-results">接下來尚無符合條件的已收錄場次。<button class="clear-button" id="reset-upcoming">查看全部樣本</button></p>`;$('reset-upcoming').addEventListener('click',()=>{resetFilters();dateSelect(data.start)});return}$('upcoming-list').innerHTML=groups.map(g=>{const d=M.parseDate(g.date);return `<button class="upcoming-card" data-date="${g.date}" aria-label="查看 ${g.date} ${esc(g.production.title)}"><span class="mini-date"><small>${d.getMonth()+1} 月</small><strong>${d.getDate()}</strong><em>${weekday(g.date)}</em></span><span class="upcoming-info"><small>${esc(g.production.city)} · ${g.times.join(' / ')}</small><h4>${esc(g.production.title)}</h4></span><span class="upcoming-arrow" aria-hidden="true">↗</span></button>`}).join('');$('upcoming-list').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{dateSelect(b.dataset.date,true);if(!window.matchMedia('(max-width:760px)').matches)document.querySelector('.calendar-layout').scrollIntoView({behavior:'smooth',block:'start'})}));}
function renderSources(){$('source-list').innerHTML=data.productions.map(p=>`<div class="source-item"><a href="${esc(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(p.title)} · ${esc(p.sourceName)} ↗</a><p><strong>${esc(p.city)} · ${esc(p.venue)}</strong></p><p>${p.sessions.map(s=>`${s.date} ${s.time}`).join(' ／ ')}</p>${p.timingSource&&p.timingSource!==p.sourceUrl?`<a href="${esc(p.timingSource)}" target="_blank" rel="noopener noreferrer">場次時間核對來源 ↗</a>`:''}<p>核對日：${esc(p.checkedAt||data.checkedAt)}。${esc(p.notes||'')}</p></div>`).join('')}
function render(){const list=M.sessions(data,state);renderFilters();renderCalendar(list);renderDay(list);renderUpcoming(list);$('coverage-count').textContent=`${new Set(data.productions.map(p=>p.productionId)).size} 部作品 · ${M.sessions(data).length} 場已核對場次`}
$('city-filter').addEventListener('change',e=>{state.city=e.target.value;render()});$('search').addEventListener('input',e=>{state.query=e.target.value;render()});$('today').addEventListener('click',()=>dateSelect(M.taipeiToday()));$('jump-date').addEventListener('change',e=>{if(/^\d{4}-\d{2}-\d{2}$/.test(e.target.value))dateSelect(e.target.value)});['prev-month','next-month'].forEach((id,i)=>$(id).addEventListener('click',()=>{const d=new Date(state.year,state.month+(i?1:-1),1,12);state.year=d.getFullYear();state.month=d.getMonth();render()}));renderSources();render();
})();
